ROOT.scriptdef:
CREATE PROCEDURE [CDN].[POS_PaczkaKontrahenci] @rowVersion bigint, @PointOfSaleId int, @packageSize int, @packageNumber int AS BEGIN SET NOCOUNT ON;
declare @maskaDostawca INT = 8, @maskaOdbiorca INT = 16
select Knt_GUID as [@GUID], Knt_Akronim as [@Code], case when Knt_Typ & @maskaDostawca <> 0 AND Knt_Typ & @maskaOdbiorca <> 0 then 0 when Knt_Typ & @maskaOdbiorca <> 0 then 1 when Knt_Typ & @maskaDostawca <> 0 then 2 end as [@Kind], 'false' as [@CanGetLowestPrice], --CO TO? case when Knt_Cena = 0 then PcK_NrCenyDomyslnej else Knt_Cena end as [@DefaultPriceTypeId], 0 as [@Points], -- Knt_Punkty TYP SIĘ NIE ZGADZA case when Knt_Archiwalny = 0 AND Knt_BlokadaTransakcji = 0 then 'true' else 'false' end as [@IsActive], CASE WHEN knt_gidnumer = 0 THEN 'True' ELSE 'False' END as [@IsDefault], 'false' as [@IsInternal], 'true' as [@IsVisible], 'true' as [@CanBeModified], DATEADD(second,Knt_LastModL,convert(datetime,'01-01-1990',105)) as [@ModificationDate], 0 as [@CreditLimitCustomerId], --NIE OBSŁUGUJEMY W 2019.1 /*case when Knt_LimitTerminowy = 0 then 'true' else 'false' end --NIE OBSŁUGUJEMY W 2019.1*/ 'true' as [@IsCreditLimitUnlimited], Knt_FormaPl as [@DefaultPaymentFormId], Knt_LimitOkres as [@DefaultPaymentDays], 'false' as [@HasEOMPayment], 0 as [@EOMPaymentCorrectByDays], Knt_ExpoKraj-1 as [@Type], case when Knt_Anonim = 1 then 'true' else 'false' end as [@IsAnonymized], 'false' as [@CanUseReverseCharge], ( select Knt_GUIDdane as [@GUID], 'true' as [@IsActive], CASE WHEN knt_gidnumer = 0 THEN 'JEDNORAZOWY' ELSE RTRIM( case when Knt_Status=2 then knt_nazwa1+' '+knt_nazwa2 else knt_nazwa1 end) END as [@Name], ISNULL(KnO_Opis,'') as [@Description], RTRIM(Knt_Nip) as [@TIN], ISNULL(kpc_id,0) as [@TINCountryId], Knt_Pesel as [@NIN], case when Knt_Status=2 then 'true' else 'false' end as [@IsRetail], Knt_OrganWydajacy as [@IdentityDocumentIssuingAuthority], Knt_DokumentTozsamosci as [@IdentityDocumentNumber], DATEADD(second,Knt_LastModL,convert(datetime,'01-01-1990',105)) as [@ModificationDate], Knt_Regon as [@EIN], --case when PATINDEX('% %',reverse(Knt_nazwa1)) <> 0 AND Knt_Status=2 then SUBSTRING(Knt_nazwa1,1,len(Knt_nazwa1) - PATINDEX('% %',reverse(Knt_nazwa1))+1) else null end as [@FirstName], --case when PATINDEX('% %',reverse(Knt_nazwa1)) <> 0 AND Knt_Status=2 then SUBSTRING(Knt_nazwa1,len(Knt_nazwa1) - PATINDEX('% %',reverse(Knt_nazwa1))+1,len(Knt_nazwa1)) else null end as [@LastName] case when Knt_Status=2 then knt_nazwa1 else null end as [@FirstName], case when Knt_Status=2 then knt_nazwa2 else null end as [@LastName] -- as [@DateOfBirth], --NULL -- as [@TitleId] --NULL for xml path('CustomerData'), root('CustomerData'), type ) from cdn.POS_KntDOEksportu(@PointOfSaleId,@rowVersion) join cdn.Kntkarty on Knt_GIDNumer = KntGidNumer LEFT JOIN CDN.KntOpisy ON KnO_KntNumer = Knt_GIDNumer LEFT JOIN CDN.KrajeCelne ON Knt_Kraj = KPC_Kod LEFT JOIN CDN.PicoStanowiska ON Psa_id = @PointOfSaleId LEFT JOIN cdn.PicoKonfig on PSa_PcKID = PcK_PicoID where KntLp between (@packageNumber-1)*@packageSize+1 and @packageNumber*@packageSize for xml path('Customer') SET NOCOUNT OFF; END
